{"condition_branches":[{"line":164,"condition":"if not (isinstance(update, Update) and update.callback_query):","branches_executed":["false","true"]},{"line":170,"condition":"if not any([self.pattern, self.game_pattern]):","branches_executed":["false","true"]},{"line":175,"condition":"if callback_data:","branches_executed":["false","true"]},{"line":176,"condition":"if not self.pattern:","branches_executed":["false","true"]},{"line":178,"condition":"if isinstance(self.pattern, type):","branches_executed":["false","true"]},{"line":180,"condition":"if callable(self.pattern):","branches_executed":["false","true"]},{"line":182,"condition":"if not isinstance(callback_data, str):","branches_executed":["false","true"]},{"line":184,"condition":"if match := re.match(self.pattern, callback_data):","branches_executed":["false","true"]},{"line":187,"condition":"elif game_short_name:","branches_executed":["false","true"]},{"line":188,"condition":"if not self.game_pattern:","branches_executed":["false","true"]},{"line":190,"condition":"if match := re.match(self.game_pattern, game_short_name):","branches_executed":["false","true"]}]}
